def parse(text: str) -> dict[str, dict[str, str]]:
    """Parse INI text."""
    sections: dict[str, dict[str, str]] = {}
    current: dict[str, str] | None = None
    last_key: str | None = None

    for lineno, raw_line in enumerate(text.splitlines(), 1):
        line = raw_line.strip()

        if not line or line[0] in "#;":
            last_key = None
            continue

        # A line starting with whitespace continues the preceding key.  This
        # is checked after comments and blank lines, which end continuations.
        if raw_line[0].isspace() and last_key is not None:
            assert current is not None
            current[last_key] += "\n" + line
            continue

        if line[0] == "[" and line[-1] == "]":
            name = line[1:-1].strip()
            current = sections.setdefault(name, {})
            last_key = None
            continue

        equals = line.find("=")
        colon = line.find(":")
        if equals == -1 and colon == -1:
            raise ParseError(lineno, "expected a section or key/value pair")
        if equals == -1:
            separator = colon
        elif colon == -1:
            separator = equals
        else:
            separator = min(equals, colon)

        key = line[:separator].strip().lower()
        value = line[separator + 1:].strip()

        if not key:
            raise ParseError(lineno, "empty key")
        if current is None:
            raise ParseError(lineno, "key outside of a section")

        current[key] = value
        last_key = key

    result: dict[str, dict[str, str]] = {}
    memo: dict[tuple[str, str], str] = {}
    for section_name, values in sections.items():
        interpolated: dict[str, str] = {}
        for key in values:
            interpolated[key] = _interpolate_value(
                sections, section_name, key, memo, set()
            )
        result[section_name] = interpolated
    return result


def _interpolate_value(
    sections: dict[str, dict[str, str]],
    section: str,
    key: str,
    memo: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
) -> str:
    """Return the fully interpolated value of ``section``/``key``."""
    token = (section, key)
    if token in memo:
        return memo[token]
    if token in active:
        raise InterpolationError(
            f"interpolation cycle involving {key!r} in section {section!r}"
        )

    active.add(token)
    try:
        value = _interpolate_text(
            sections, section, sections[section][key], memo, active
        )
    finally:
        active.remove(token)

    memo[token] = value
    return value


def _interpolate_text(
    sections: dict[str, dict[str, str]],
    section: str,
    text: str,
    memo: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
) -> str:
    """Interpolate one value, without rescanning inserted literals."""
    pieces: list[str] = []
    index = 0
    length = len(text)

    while index < length:
        char = text[index]

        if char != "$":
            pieces.append(char)
            index += 1
            continue

        if index + 1 < length and text[index + 1] == "$":
            # A literal dollar, which must not be rescanned for references.
            pieces.append("$")
            index += 2
            continue

        if index + 1 < length and text[index + 1] == "{":
            end = text.find("}", index + 2)
            if end != -1:
                reference = text[index + 2:end]
                pieces.append(
                    _resolve_reference(
                        sections, section, reference, memo, active
                    )
                )
                index = end + 1
                continue
            # Unterminated "${": the dollar is just a literal dollar.

        pieces.append("$")
        index += 1

    return "".join(pieces)


def _resolve_reference(
    sections: dict[str, dict[str, str]],
    section: str,
    reference: str,
    memo: dict[tuple[str, str], str],
    active: set[tuple[str, str]],
) -> str:
    """Resolve the text between "${" and "}"."""
    if ":" in reference:
        target_section, target_key = reference.split(":", 1)
        target_key = target_key.lower()
    else:
        target_section = section
        target_key = reference.lower()

    if target_section not in sections:
        raise InterpolationError(f"missing section {target_section!r}")
    if target_key not in sections[target_section]:
        raise InterpolationError(
            f"missing key {target_key!r} in section {target_section!r}"
        )

    return _interpolate_value(
        sections, target_section, target_key, memo, active
    )

